import json
import math
import os
import sys
from datetime import datetime, timezone

REQUIRED = ["application", "prompt", "model", "retrieval", "tool", "policy", "data", "infrastructure", "grader"]
ROLES = ["product", "risk", "operations"]
FILES = ["manifest.json", "evidence.json", "approvals.json", "rollback.json", "reconciliation.json", "canary.json", "decision.json"]
TRUE_FIELDS = ["critical_slices_reviewed", "severe_failures_reviewed", "security", "privacy", "safety", "accessibility", "capacity_ok", "cost_ok", "observability", "incident_owner", "dependency_ok", "migration_compatible", "retention_reviewed", "reversibility_verified"]


def result(status, reasons):
    return {"status": status, "reasons": sorted(set(reasons)), "authorization": "NONE", "deployment": "NOT_PERFORMED"}


def parse_time(value):
    if not isinstance(value, str) or not value.endswith("Z"):
        raise ValueError("timestamp must be a UTC Z string")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.tzinfo is None or parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise ValueError("timestamp must be UTC")
    return parsed


def number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def integer(value):
    return isinstance(value, int) and not isinstance(value, bool)


def nonempty(value):
    return isinstance(value, str) and bool(value.strip())


def pair(value):
    return isinstance(value, list) and len(value) == 2 and all(nonempty(x) for x in value)


def load_all(root):
    loaded = {}
    problems = []
    for filename in FILES:
        path = os.path.join(root, filename)
        try:
            with open(path, encoding="utf-8") as handle:
                value = json.load(handle)
            if not isinstance(value, dict):
                problems.append(filename + "-top-level-must-be-object")
            else:
                loaded[filename] = value
        except FileNotFoundError:
            problems.append(filename + "-missing")
        except (OSError, UnicodeError, json.JSONDecodeError):
            problems.append(filename + "-unreadable-or-malformed")
    return loaded, problems


def check(root):
    docs, hold = load_all(root)
    reject = []
    if hold:
        return result("HOLD", hold)

    m = docs["manifest.json"]
    e = docs["evidence.json"]
    a = docs["approvals.json"]
    r = docs["rollback.json"]
    q = docs["reconciliation.json"]
    c = docs["canary.json"]
    d = docs["decision.json"]

    cid = m.get("candidate_id")
    if not nonempty(cid):
        hold.append("missing-or-invalid-candidate-id")
        cid = None
    for obj, label in [(e, "evidence"), (a, "approvals"), (r, "rollback"), (q, "reconciliation"), (c, "canary"), (d, "decision")]:
        other = obj.get("candidate_id")
        if not nonempty(other):
            hold.append(label + "-candidate-id-invalid")
        elif cid is not None and other != cid:
            reject.append(label + "-candidate-mismatch")

    try:
        now = parse_time(m.get("as_of"))
    except (TypeError, ValueError, OverflowError):
        now = None
        hold.append("as-of-unknown")

    components = m.get("components")
    if not isinstance(components, dict):
        components = {}
        hold.append("components-must-be-object")
    unknown_components = sorted(set(components) - set(REQUIRED))
    if unknown_components:
        hold.append("unknown-component-boundary")
    for boundary in REQUIRED:
        if not pair(components.get(boundary)):
            hold.append("invalid-component-" + boundary)

    thresholds = m.get("thresholds")
    if not isinstance(thresholds, dict):
        thresholds = {}
        hold.append("thresholds-must-be-object")
    rep_threshold = thresholds.get("representative_pass_rate")
    critical_threshold = thresholds.get("critical_failures")
    manifest_error_budget = thresholds.get("error_budget")
    manifest_cost_ceiling = thresholds.get("cost_ceiling")
    if not number(rep_threshold) or not 0 <= rep_threshold <= 1:
        hold.append("representative-threshold-invalid")
    if not integer(critical_threshold) or critical_threshold != 0:
        hold.append("critical-threshold-invalid")
    if not number(manifest_error_budget) or not 0 <= manifest_error_budget <= 1:
        hold.append("manifest-error-budget-invalid")
    if not number(manifest_cost_ceiling) or manifest_cost_ceiling < 0:
        hold.append("manifest-cost-ceiling-invalid")

    owners = m.get("owners")
    if not isinstance(owners, dict):
        owners = {}
        hold.append("owners-must-be-object")
    for role in ROLES:
        if not nonempty(owners.get(role)):
            hold.append(role + "-owner-missing")
    if not nonempty(m.get("rollback_method")):
        hold.append("rollback-method-missing")
    if not pair(m.get("previous_verified")):
        hold.append("previous-verified-invalid")
    links = m.get("record_links")
    if not isinstance(links, dict) or not links or any(not nonempty(v) for v in links.values()):
        hold.append("manifest-record-links-invalid")

    records = e.get("records")
    if not isinstance(records, list):
        records = []
        hold.append("evidence-records-must-be-list")
    by_boundary = {}
    for item in records:
        if not isinstance(item, dict):
            hold.append("evidence-record-must-be-object")
            continue
        boundary = item.get("boundary")
        if not nonempty(boundary):
            hold.append("evidence-boundary-invalid")
            continue
        if boundary in by_boundary:
            hold.append("duplicate-evidence-boundary-" + boundary)
            continue
        by_boundary[boundary] = item
    if set(by_boundary) - set(REQUIRED):
        hold.append("unknown-evidence-boundary")
    for boundary in REQUIRED:
        item = by_boundary.get(boundary)
        expected = components.get(boundary)
        if item is None:
            hold.append("missing-" + boundary)
            continue
        if not pair(expected):
            continue
        if item.get("id") != expected[0] or item.get("hash") != expected[1]:
            reject.append(boundary + "-binding-mismatch")
        status = item.get("status")
        if status == "FAIL":
            reject.append(boundary + "-evidence-failed")
        elif status != "PASS":
            hold.append(boundary + "-evidence-status-unknown")
        if not nonempty(item.get("record_link")):
            hold.append(boundary + "-record-link-missing")
        try:
            expires = parse_time(item.get("expires"))
            if now is not None and expires <= now:
                hold.append(boundary + "-evidence-stale-or-expired")
        except (TypeError, ValueError, OverflowError):
            hold.append(boundary + "-expiry-unknown")

    ev = e.get("evaluation")
    if not isinstance(ev, dict):
        ev = {}
        hold.append("evaluation-must-be-object")
    if not nonempty(ev.get("record_link")):
        hold.append("evaluation-record-link-missing")
    for key in TRUE_FIELDS:
        value = ev.get(key)
        if not isinstance(value, bool):
            hold.append(key + "-must-be-boolean")
        elif value is False:
            reject.append(key + "-failed")
    pass_rate = ev.get("representative_pass_rate")
    if not number(pass_rate) or not 0 <= pass_rate <= 1:
        hold.append("representative-pass-rate-invalid")
    elif number(rep_threshold) and 0 <= rep_threshold <= 1 and pass_rate < rep_threshold:
        reject.append("representative-threshold-failed")
    failures = ev.get("critical_failures")
    if not integer(failures) or failures < 0:
        hold.append("critical-failure-count-invalid")
    elif failures != 0:
        reject.append("critical-failure-count-not-zero")

    approvals = a.get("approvals")
    if not isinstance(approvals, list):
        approvals = []
        hold.append("approvals-must-be-list")
    seen_roles = set()
    for item in approvals:
        if not isinstance(item, dict):
            hold.append("approval-record-must-be-object")
            continue
        role = item.get("role")
        if role not in ROLES:
            hold.append("unknown-approval-role")
            continue
        if role in seen_roles:
            hold.append("duplicate-approval-role-" + role)
            continue
        seen_roles.add(role)
        if not nonempty(item.get("name")):
            hold.append(role + "-approval-name-empty")
        if not isinstance(item.get("approved"), bool):
            hold.append(role + "-approval-must-be-boolean")
        elif item.get("approved") is False:
            hold.append(role + "-approval-not-recorded")
        if not nonempty(item.get("record_link")):
            hold.append(role + "-approval-link-missing")
    for role in ROLES:
        if role not in seen_roles:
            hold.append("missing-role-approval-" + role)
    if a.get("authorization") != "NONE":
        hold.append("exercise-authorization-must-be-none")

    rollback = r.get("rollback")
    if not isinstance(rollback, dict):
        rollback = {}
        hold.append("rollback-record-must-be-object")
    for key in ["id", "record_link", "proposed_method"]:
        if not nonempty(rollback.get(key)):
            hold.append("rollback-" + key.replace("_", "-") + "-invalid")
    if rollback.get("status") == "FAIL":
        reject.append("rollback-rehearsal-failed")
    elif rollback.get("status") != "PASS":
        hold.append("rollback-status-unknown")
    if rollback.get("executed_in_production") is not False:
        hold.append("rollback-execution-state-invalid")
    if not pair(rollback.get("previous_verified")) or rollback.get("previous_verified") != m.get("previous_verified"):
        hold.append("rollback-previous-verified-invalid")

    reconciliation = q.get("reconciliation")
    if not isinstance(reconciliation, dict):
        reconciliation = {}
        hold.append("reconciliation-record-must-be-object")
    for key in ["id", "record_link", "scope"]:
        if not nonempty(reconciliation.get(key)):
            hold.append("reconciliation-" + key.replace("_", "-") + "-invalid")
    if reconciliation.get("status") == "FAIL":
        reject.append("reconciliation-failed")
    elif reconciliation.get("status") != "PASS":
        hold.append("reconciliation-status-unknown")
    if reconciliation.get("executed_in_production") is not False:
        hold.append("reconciliation-execution-state-invalid")

    if not nonempty(c.get("record_link")):
        hold.append("canary-record-link-missing")
    count_fields = ["population", "duration_minutes", "events", "errors", "critical_events"]
    for key in count_fields:
        if not integer(c.get(key)):
            hold.append(key + "-must-be-integer")
    if integer(c.get("population")) and c["population"] <= 0:
        hold.append("population-must-be-positive")
    if integer(c.get("duration_minutes")) and c["duration_minutes"] <= 0:
        hold.append("duration-must-be-positive")
    if integer(c.get("events")) and c["events"] <= 0:
        hold.append("canary-events-must-be-positive")
    if integer(c.get("errors")) and c["errors"] < 0:
        hold.append("canary-errors-must-be-nonnegative")
    if integer(c.get("critical_events")) and c["critical_events"] < 0:
        hold.append("critical-events-must-be-nonnegative")
    if integer(c.get("events")) and integer(c.get("errors")) and c["events"] >= 0 and c["errors"] > c["events"]:
        hold.append("canary-errors-exceed-events")
    for key in ["cost", "error_budget", "cost_ceiling"]:
        if not number(c.get(key)):
            hold.append(key + "-must-be-finite-number")
    if number(c.get("cost")) and c["cost"] < 0:
        hold.append("canary-cost-must-be-nonnegative")
    if number(c.get("error_budget")) and not 0 <= c["error_budget"] <= 1:
        hold.append("canary-error-budget-invalid")
    if number(c.get("cost_ceiling")) and c["cost_ceiling"] < 0:
        hold.append("canary-cost-ceiling-invalid")
    if number(c.get("error_budget")) and number(manifest_error_budget) and c["error_budget"] != manifest_error_budget:
        reject.append("canary-error-budget-mismatch")
    if number(c.get("cost_ceiling")) and number(manifest_cost_ceiling) and c["cost_ceiling"] != manifest_cost_ceiling:
        reject.append("canary-cost-ceiling-mismatch")
    if not nonempty(c.get("manual_kill")):
        hold.append("manual-kill-invalid")
    if c.get("auto_stop") is not True:
        hold.append("auto-stop-must-be-true")
    arithmetic_safe = integer(c.get("events")) and c["events"] > 0 and integer(c.get("errors")) and 0 <= c["errors"] <= c["events"] and number(c.get("error_budget")) and 0 <= c["error_budget"] <= 1
    if arithmetic_safe and c["errors"] / c["events"] > c["error_budget"]:
        reject.append("canary-error-budget-exceeded")
    if number(c.get("cost")) and c["cost"] >= 0 and number(c.get("cost_ceiling")) and c["cost_ceiling"] >= 0 and c["cost"] > c["cost_ceiling"]:
        reject.append("canary-cost-ceiling-exceeded")
    if integer(c.get("critical_events")) and c["critical_events"] > 0:
        reject.append("critical-canary-event-stop")

    if not nonempty(d.get("record_id")) or not nonempty(d.get("record_link")):
        hold.append("decision-record-link-invalid")
    if d.get("automated_state") != "ELIGIBLE_FOR_HUMAN_REVIEW":
        hold.append("decision-automated-state-invalid")
    if d.get("human_decision") != "NOT_RECORDED":
        hold.append("exercise-human-decision-must-be-not-recorded")
    if d.get("authorization") != "NONE":
        hold.append("decision-authorization-must-be-none")
    if d.get("deployment") != "NOT_PERFORMED":
        hold.append("decision-deployment-must-be-not-performed")
    if not isinstance(d.get("waivers"), list):
        hold.append("waivers-must-be-list")
    if d.get("closeout_evidence") != "UNKNOWN":
        hold.append("exercise-closeout-must-be-unknown")

    status = "REJECT" if reject else ("HOLD" if hold else "ELIGIBLE_FOR_HUMAN_REVIEW")
    return result(status, reject + hold)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(json.dumps(result("HOLD", ["usage-python3-validator-py-fixture-directory"]), sort_keys=True))
    else:
        print(json.dumps(check(sys.argv[1]), sort_keys=True))

import copy
import json
import math
import os
import tempfile
import unittest
from pathlib import Path

import validator

BASE = Path(__file__).parent / "fixtures" / "baseline"
FILES = validator.FILES


def read_baseline():
    return {name: json.loads((BASE / name).read_text(encoding="utf-8")) for name in FILES}


class GateTests(unittest.TestCase):
    def run_docs(self, mutate=None, omit=None, malformed=None):
        docs = copy.deepcopy(read_baseline())
        if mutate:
            mutate(docs)
        with tempfile.TemporaryDirectory() as root:
            for name, value in docs.items():
                if name == omit:
                    continue
                path = Path(root) / name
                if name == malformed:
                    path.write_text("{not-json", encoding="utf-8")
                else:
                    path.write_text(json.dumps(value), encoding="utf-8")
            return validator.check(root)

    def assert_status_reason(self, output, status, reason):
        self.assertEqual(output["status"], status)
        self.assertIn(reason, output["reasons"])
        self.assertEqual(output["authorization"], "NONE")
        self.assertEqual(output["deployment"], "NOT_PERFORMED")

    def test_baseline_eligible_without_authority(self):
        out = self.run_docs()
        self.assertEqual(out, {"status":"ELIGIBLE_FOR_HUMAN_REVIEW","reasons":[],"authorization":"NONE","deployment":"NOT_PERFORMED"})

    def test_expiry_boundary_is_hold(self):
        out = self.run_docs(lambda d: d["evidence.json"]["records"][0].update(expires=d["manifest.json"]["as_of"]))
        self.assert_status_reason(out, "HOLD", "application-evidence-stale-or-expired")

    def test_stale_evidence_is_hold(self):
        out = self.run_docs(lambda d: d["evidence.json"]["records"][0].update(expires="2026-09-13T11:59:59Z"))
        self.assert_status_reason(out, "HOLD", "application-evidence-stale-or-expired")

    def test_missing_boundary_is_hold(self):
        def change(d): d["evidence.json"]["records"] = [x for x in d["evidence.json"]["records"] if x["boundary"] != "retrieval"]
        self.assert_status_reason(self.run_docs(change), "HOLD", "missing-retrieval")

    def test_failed_boundary_is_reject(self):
        self.assert_status_reason(self.run_docs(lambda d: d["evidence.json"]["records"][0].update(status="FAIL")), "REJECT", "application-evidence-failed")

    def test_binding_mismatch_is_reject(self):
        self.assert_status_reason(self.run_docs(lambda d: d["evidence.json"]["records"][2].update(hash="sha256:wrong")), "REJECT", "model-binding-mismatch")

    def test_critical_failure_is_reject(self):
        self.assert_status_reason(self.run_docs(lambda d: d["evidence.json"]["evaluation"].update(critical_failures=1)), "REJECT", "critical-failure-count-not-zero")

    def test_pass_rate_bool_is_hold(self):
