    def test_error_budget_exceeded_is_reject(self):
        self.assert_status_reason(self.run_docs(lambda d: d["canary.json"].update(errors=3)), "REJECT", "canary-error-budget-exceeded")

    def test_cost_ceiling_exceeded_is_reject(self):
        self.assert_status_reason(self.run_docs(lambda d: d["canary.json"].update(cost=0.51)), "REJECT", "canary-cost-ceiling-exceeded")

    def test_critical_canary_overrides_hold(self):
        out = self.run_docs(lambda d: d["canary.json"].update(critical_events=1, auto_stop="true"))
        self.assert_status_reason(out, "REJECT", "critical-canary-event-stop")
        self.assertIn("auto-stop-must-be-true", out["reasons"])

    def test_missing_file_is_controlled_hold(self):
        self.assert_status_reason(self.run_docs(omit="canary.json"), "HOLD", "canary.json-missing")

    def test_malformed_json_is_controlled_hold(self):
        self.assert_status_reason(self.run_docs(malformed="evidence.json"), "HOLD", "evidence.json-unreadable-or-malformed")

    def test_unknown_timestamp_is_hold(self):
        self.assert_status_reason(self.run_docs(lambda d: d["manifest.json"].update(as_of="UNKNOWN")), "HOLD", "as-of-unknown")

    def test_invalid_expiry_is_hold(self):
        self.assert_status_reason(self.run_docs(lambda d: d["evidence.json"]["records"][0].update(expires="UNKNOWN")), "HOLD", "application-expiry-unknown")

    def test_changed_candidate_solution(self):
        def change(d):
            new_id = "candidate-2026-09-13-b"
            d["manifest.json"]["candidate_id"] = new_id
            d["manifest.json"]["components"]["model"] = ["model-5", "sha256:model-new"]
            d["evidence.json"]["candidate_id"] = new_id
            d["evidence.json"]["records"][2].update(id="model-5", hash="sha256:model-new")
            d["rollback.json"]["candidate_id"] = new_id
            d["reconciliation.json"]["candidate_id"] = new_id
            d["canary.json"]["candidate_id"] = new_id
            d["canary.json"]["critical_events"] = 1
            d["decision.json"]["candidate_id"] = new_id
        out = self.run_docs(change)
        self.assertEqual(out["status"], "REJECT")
